use xiom.io;

enum LoginResult {
  Success(username: Str),
  WrongPassword,
  UserNotFound,
}

fn try_login(user: Str, pass: Str) -> LoginResult {
  if user != "admin" {
    return LoginResult.UserNotFound;
  }
  if pass != "secret123" {
    return LoginResult.WrongPassword;
  }
  return LoginResult.Success(user);
}

fn is_success(r: LoginResult) -> Bool {
  match r {
    Success(_) => { return true; }
    _ => { return false; }
  }
}

fn main() -> Int {
  let r1 = try_login("admin", "secret123");
  let r2 = try_login("admin", "badpass");
  let r3 = try_login("stranger", "x");
  var count = 0;
  if is_success(r1) { count = count + 1; }
  if is_success(r2) { count = count + 1; }
  if is_success(r3) { count = count + 1; }
  return count;
}
